// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Non-reverting ERC20 that returns false on transferFrom
    IERC20Mock public mockToken;

    function testFuzz_property(address user, uint96 amount) public {
        vm.assume(user != address(0) && user != address(c));
        vm.assume(amount > 0 && amount <= type(uint96).max);

        // Deploy mock token that returns false on transferFrom
        mockToken = new IERC20Mock();

        // Replace stakingToken with our mock via constructor? No, use a hack: deploy new C with mock
        // Since setUp uses address(this) as stakingToken, we redeploy C with mock
        c = new C(address(mockToken), address(this));

        // Add reward token to enable updateReward modifier
        c.addReward(address(0x1));

        // Give user some mock tokens
        mockToken.mint(user, amount);

        // User tries to stake - should revert with safeTransferFrom, pass with transferFrom
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.stakeFor.selector, user, amount));

        // The rule: staking should revert because mock token returns false
        assertTrue(!success, "stakeFor should revert when token.transferFrom returns false");
    }
}

contract IERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return false; // Non-standard: returns false instead of reverting
    }

    function transfer(address, uint256) external returns (bool) {
        return false;
    }

    function approve(address, uint256) external returns (bool) {
        return true;
    }

    function totalSupply() external view returns (uint256) { return 0; }
}

